from agent.documents.credit_pdf.junk_filter import (
    is_junk_creditor_name, dedupe_tradelines,
)
from agent.documents.credit_pdf.models import ParsedTradeline
from agent.documents.credit_pdf.normalize import (
    bureau_tags_from_text, is_plausible_creditor_line, is_creditor_boilerplate_line,
)

# A: filler tokens in any case are filtered; usual forms still filtered
for tok in ("unknown", "Unknown", "UNKNOWN", "N/A", "n/a", "NA", "Unknown Creditor", "UNKNOWN CREDITOR"):
    assert is_junk_creditor_name(tok), tok
assert not is_junk_creditor_name("JPMCB CARD SERVICES")

# B: case-variant duplicates collapse; distinct rows survive
tls = [
    ParsedTradeline(creditor="CHASE BANK", account_number="1234"),
    ParsedTradeline(creditor="Chase Bank", account_number="1234"),
    ParsedTradeline(creditor="Chase Bank", account_number="9999"),
]
out = dedupe_tradelines(tls)
assert len(out) == 2, [t.creditor for t in out]

# C: digit-leading creditors survive; numeric/money lines still rejected
for good in ("1ST FINANCIAL BANK USA", "21ST MORTGAGE CORP", "5/3 BANK"):
    assert is_plausible_creditor_line(good), good
    assert not is_junk_creditor_name(good), good
for junk in ("$1,234.56", "1,234", "100%", "  12 "):
    assert not is_plausible_creditor_line(junk), junk
# boilerplate prefixes need word boundary
assert not is_creditor_boilerplate_line("PAYMENTECH LLC")
assert not is_creditor_boilerplate_line("BALANCE CREDIT")
for bp in ("Payment (Min.)", "Balance", "Past Due", "Comment", "Released: 01/02/2024", "Loan Number: 55", "$500"):
    assert is_creditor_boilerplate_line(bp), bp

# D: EFX variant attributes to equifax; other variants unchanged; untagged empty
assert bureau_tags_from_text("EFX-B1") == {"equifax"}
assert bureau_tags_from_text("EQX-B1") == {"equifax"}
assert bureau_tags_from_text("TUC-B1, EXP-B2") == {"transunion", "experian"}
assert bureau_tags_from_text("TU-B1") == {"transunion"}
assert bureau_tags_from_text("no tags here") == set()
print("all findings reconcile")
EOF

